code='''def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(value for row in grid for value in row).most_common(1)[0][0]
    original = [[grid[r][c] != bg for c in range(w)] for r in range(h)]
    points = [(r, c) for r in range(h) for c in range(w) if original[r][c]]
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    axis_sum = left + right
    out = [row[:] for row in grid]
    occupied = [row[:] for row in original]
    # Reflect the marked pattern across the vertical center of its bounding box.
    for r, c in points:
        mirror = axis_sum - c
        if 0 <= mirror < w:
            occupied[r][mirror] = True
            if not original[r][mirror]:
                out[r][mirror] = 2
    # Fill short horizontal gaps between marks after reflection.
    for r in range(h):
        cols = [c for c in range(w) if occupied[r][c]]
        for a, b in zip(cols, cols[1:]):
            if b - a <= 3:
                for c in range(a + 1, b):
                    out[r][c] = 2
                    occupied[r][c] = True
    # Fill short vertical gaps only when they join separate marked components.
    labels = [[-1] * w for _ in range(h)]
